def sym_fill(I):
    g=[row[:] for row in I]; n=30
    changed=True
    while changed:
        changed=False
        for r in range(n):
            for c in range(n):
                if g[r][c]==6:
                    for (rr,cc) in [(c,r),(31-r,31-c),(31-c,31-r)]:
                        if 0<=rr<30 and 0<=cc<30 and g[rr][cc]!=6:
                            g[r][c]=g[rr][cc]; changed=True; break
    return g
